    'SettingsDesc'                        => 'Konfigureer stelselwye instellings: Basis-URL, sekuriteit, verstektaal, tydsone, risikotelling-verstekwaardes en meer.',
    'SettingsPreferencesDesc'             => 'Verstekwaardes en gedragsvoorkeure regdeur SimpleRisk: taal, tydsone, oudit-statusse, vereistes vir risikokartering, skakelaars vir gebruikerskoppelvlakgedrag, en soortgelyke.',
    'SettingsFileUploadDesc'              => 'Toegelate lêeroplaaitipes en groottelimiete vir die verskillende lêeraanhangselvelde.',
    'SettingsMailDesc'                    => 'SMTP-konfigurasie vir uitgaande e-poskennisgewings, insluitend vervoer, gasheer, verifikasie en antwoord-aan.',
    'SettingsBackupsDesc'                 => 'Konfigureer rugsteunbehoud, skedulering en aflaaiskakels vir SimpleRisk-databasisrugsteun.',
    'SettingsSecurityDesc'                => 'Verifikasie, sessie, wagwoordbeleid, basis-URL en API-sekuriteitsinstellings.',
    'SettingsLoggingDesc'                 => 'Opstelling van ontfoutings- en oudit-logboekvoering: logboekvlakke, bewaring en die ligging van logboeklêers.',
    'HealthCheckDesc'                     => 'Diagnoseer stelselstatus: PHP-weergawe, uitbreidings, lêertoestemmings, databasiskonnektiwiteit, cron-skedule en aktiverings van Ekstras.',
    'AnnouncementsDesc'                   => 'Stel banier-aankondigings op en bestuur dit, sigbaar vir alle gebruikers.',
    'RegisterAndUpgradeDesc'              => 'Registreer jou SimpleRisk-installasie, voer \'n intekeningsleutel in of hernu dit, en aktiveer Core/Extra-opgraderings met een klik.',
    'QueueMonitorDesc'                    => 'Inspekteer die agtergrondtaakwaglys: hangende, aan die gang en mislukte take.',
    'ExtrasDesc'                          => 'Aktiveer, deaktiveer en konfigureer SimpleRisk Extras (betaalde byvoegings).',
    'ArtificialIntelligenceExtraDesc'     => 'Die Kunsmatige Intelligensie Ekstra bied verbeterde risiko-analise (insluitend FAIR-assesserings) en aangepaste dokumentasie.',
    'CustomizationExtraDesc'              => 'Die Customization-Ekstra maak dit moontlik om verskillende tipes velde by te voeg en te verwyder en om dinamies pasgemaakte bladsysjablone te skep.',
    'NotificationExtraDesc'               => 'Die Email Notification-Ekstra stel SimpleRisk in staat om e-poskennisgewings te stuur wanneer risiko\'s ingedien, gewysig of andersins op aksie geneem word. Hierdie ekstra kan ook as \'n geskeduleerde skrip bygevoeg word om gereelde herinnerings te stuur wanneer risiko\'s gereed is vir \'n bestuurshersiening. In die SimpleRisk Core-produk, sonder hierdie Ekstra, word geen kennisgewings buite die instrument self gekommunikeer nie.',
    'VulnerabilityManagementExtraDesc'    => 'Die Vulnerability Management-Ekstra bied kliënte die vermoë om hul SimpleRisk-instansie met Qualys, Tenable.io of Rapid7 Nexpose/InsightVM te integreer en sowel bate- as kwesbaarheidsdata in SimpleRisk in te voer. Van daar af kan jy kies watter werwe jy wil dek, bepaal watter kwesbaarheidstellings ingevoer moet word, en triageer watter kwesbaarhede in risiko\'s omgeskakel word om hulle op te spoor.',
    'IncidentManagementExtraDesc'         => 'Die Incident Management-Ekstra is gebaseer op die NIST 800-61 Computer Security Incident Handling Guide en bied voorvalbestuurvermoëns binne die SimpleRisk-stelsel.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Hernoem SimpleRisk-terminologie (Risiko, Bate, Raamwerk, ens.) regdeur die gebruikerskoppelvlak.',
    'RiskConfigurationDesc'               => 'Konfigureer risikotellingreëls: vlakke, aptyt, SLA-drempels en die klassieke / bydraende risikoformules.',
    'RiskAndThreatCatalogDesc'            => 'Handhaaf die katalogus van risiko- en bedreigingswaardes wat in aftreklyste gebruik word.',
    'AddAndRemoveValuesDesc'              => 'Bestuur die aftreklyswaardes vir risikovelde: ligging, bron, kategorie, span, tegnologie en meer.',
    'AssetValuationDesc'                  => 'Konfigureer die batewaardasieskaal en per-bate waardasie-oorskrywings.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Voeg gebruikers by, wysig, deaktiveer en stel hulle terug; bestuur wagwoordbeleid.',
    'RoleManagementDesc'                  => 'Definieer rolle en die toestemmings wat elke rol toeken.',
    'TeamManagementDesc'                  => 'Skep en bestuur spanne wat gebruik word vir rekordsigbaarheidsfiltering.',
    'SeparationExtraDesc'                 => 'Die Team-Based Separation-Ekstra beperk risikovertoning tot slegs die gebruikers wat lede is van die span aan wie die risiko toegewys is. In die SimpleRisk Core-produk, sonder hierdie Ekstra, kan elke gebruiker elke risiko sien.',
    'CustomAuthenticationExtraDesc'       => 'Die Pasgemaakte Verifikasie Ekstra bied ondersteuning vir Active Directory en SAML-verifikasie. In die SimpleRisk Core-produk, sonder hierdie Ekstra, is die enigste opsie om nuwe gebruikers in die SimpleRisk-identiteitsbewaarplek te skep.',
    'EncryptionExtraDesc'                 => 'Die Geënkripteerde Databasis Ekstra genereer \'n ewekansige AES-256-bis enkripsiesleutel en gebruik dit dan om sensitiewe teks te enkripteer voordat dit in die SimpleRisk-databasis ingevoeg word. Dit verhoed dat enigiemand die data kan bekyk of wysig sonder om die SimpleRisk-toepassing direk te gebruik.',
    'OrganizationManagementDesc'          => "Die Organisatoriese Hiërargie Ekstra maak dit moontlik om verskeie Besigheidseenhede te definieer wat enige aantal spanne kan insluit. Gebruikers kan dan aan een of meer spanne onder verskeie Besigheidseenhede toegewys word. Dit beïnvloed 'n gebruiker se vermoë om die spanne, gebruikers en bates waarmee hulle nie geassosieer word nie, te sien en te gebruik.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Verwyder risiko\'s in grootmaat. Gebruik spaarsamig — verwyderings is permanent.',
    'AuditTrailDesc'                      => 'Soek en voer die stelselouditlogboek van gebruikersaksies uit.',
    'ImportExportExtraDesc'               => 'Die Invoer-Uitvoer Ekstra bied die vermoë om data in SimpleRisk in te voer deur velde in \'n CSV-lêer te karteer na velde in die SimpleRisk-databasis. Dit kan gebruik word om ouditresultate vanaf \'n derdeparty-sigblad, kwesbaarheidskanderingsresultate vanaf \'n ander instrument, bates vanaf jou CMDB en meer in te voer. Die Ekstra bied ook die vermoë om CSV-lêers vanaf SimpleRisk uit te voer wat Risiko\'s, Versagtings, Hersienings of \'n Kombinasieverslag van al drie bevat.',
    'JiraExtraDesc'                       => 'Die Jira Integration-Ekstra bied gebruikers die vermoë om tweerigting met \'n Jira-instansie te integreer. Dit maak dit moontlik om risiko\'s aan Jira-kwessies te koppel, asook om hul data, status en kommentaar te sinkroniseer.',
    'APIExtraDesc'                        => 'Die API-Ekstra laat kliënte toe om \'n RESTful API te gebruik om geskripte interaksies met ander toepassings te skep vir gevorderde outomatisering en om bestaande infrastruktuur te benut.',
    'AdvancedSearchExtraDesc'             => 'Die Advanced Search-Ekstra verander die soekkassie in die boonste balk in een soektog oor risiko\'s, raamwerke, beheermaatreëls, dokumente, uitsonderings, toetse, oudits, bates en bategroepe, met \'n volledige Soek-bladsy om deur die resultate te werk. Dit wys slegs rekords wat die gebruiker mag sien.',
    'AssessmentsExtraDesc'                => 'Die Risk Assessment-Ekstra bied gebruikers die vermoë om kontakte te definieer, vrae te skep (insluitend logika), verskeie vrae met \'n vraelyssjabloon saam te stel, vraelyste te skep en na kontakte te stuur, die vraelysresultate te sien, risiko\'s gebaseer op daardie resultate by te voeg, die resultate oor tyd te vergelyk, ekstern pasgemaakte assesserings in te voer en uit te voer, en die risiko-assesseringsouditspoor te hersien.',
    'ActiveAssessmentsDesc'               => 'Bekyk en bestuur assesserings wat tans aan die gang is.',
    'WorkflowsExtraDesc'                  => 'Die Workflows-Ekstra bied \'n visuele, gebeurtenisgedrewe werkvloeienjin wat risikobestuuraksies outomatiseer in reaksie op gebeure binne SimpleRisk. Jy kan werkvloeie ontwerp wat op veranderinge geaktiveer word — soos \'n risiko wat ingedien, opgedateer of hersien word — om goedkeurings te roeteer, werk toe te wys en jou proses aan die gang te hou sonder handmatige ingryping.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'Die Secure Controls Framework (SCF) Extra is \'n direkte integrasie tussen die Secure Controls Framework en SimpleRisk. Dit voer die SCF se katalogus van kontroles en hulle kartering oor \'n wye reeks nakoming- en kuberveiligheidsraamwerke in SimpleRisk se Bestuur-funksionaliteit in, sodat jy die raamwerke wat jy benodig kan aanneem en hulle kontroles kan bestuur sonder om dit met die hand te bou.',

