    'EncryptionRestoreTitle'                => 'Herstel vanaf rugsteun?',
    'EncryptionRestoreBodyWhy'              => 'Rol terug na die momentopname van voor enkripsie wat aan die begin van die mees onlangse aktivering geneem is. Kies dit as jou validering ná aktivering probleme gevind het en jy enkripsie moet laat vaar.',
    'EncryptionRestoreBodyWhat'             => 'Elke ry wat na die databasis geskryf is nadat die rugsteun geskep is, sal permanent verlore gaan – insluitend risiko\'s, versagtingsmaatreëls, ouditlogboekinskrywings en enige ander veranderinge wat sedert aktivering aangebring is. Die Geënkripteerde Databasis Ekstra sal as deel van die herstel gedeaktiveer word.',
