    'AuditLog_ControlStatusAutoSynced' => 'Die status van beheer "{$short_name}" is outomaties opgedateer na "{$status_text}" op grond van die mees onlangse toetsresultaat/-resultate.',
    'EnableCSPHelp' => 'Content Security Policy (CSP) beperk die blaaier om skrifte, style, beelde en fonte slegs vanaf SimpleRisk self te laai, en blokkeer bladsyraming en kruis-oorsprong vorminsendings. Dit is die sterkste ingeboude verdediging teen cross-site scripting. Laat geaktiveer tensy dit bots met \'n instaanbediener, blaaieruitbreiding of derdeparty-integrasie in jou omgewing.',
    // Define Control Frameworks' Columns picker (Task: Columns picker + saved layout/filters) -- the "Standard" group label above its built-in fields (Family/Owner/Maturity/Status/Class/Phase/Priority/Type); 'CustomFields' already exists.
