    'AssetScoring' => 'Batetelling',
    'AssetScoringSettingsHint' => 'Elke bate word as Laag, Matig of Hoog ggradeer vir vertroulikheid, integriteit en beskikbaarheid, en vertroulikheid kan eerder Nie van toepassing nie wees, wat dit uit albei resultate laat. Die FIPS-kategorisering daarvan is die hoogste van die drie graderings. Die geweegde telling daarvan is die geweegde gemiddelde van die drie vlakwaardes, en die reeksdrempels omskep daardie telling in \'n Lae, Matige of Hoë reeks. As hierdie instellings verander word, word elke bate onmiddellik herbereken.',
